               <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
               <input
                 id="phone"
                 name="phone"
                 type="tel"
                 autocomplete="tel"
                 aria-describedby="phone-help phone-error"
               >
               <p class="help-text" id="phone-help">Expected format: 7 to 15 digits. Spaces, dashes, parentheses, and an optional leading + are accepted.</p>
               <p class="error-message" id="phone-error"></p>
             </div>

             <button type="submit">Send request</button>
             <p class="status-message" id="form-status" aria-live="polite"></p>
           </form>
         </div>
       </section>
     </main>

     <script>
       const form = document.querySelector("#support-form");
       const statusMessage = document.querySelector("#form-status");
       const fields = {
         fullName: {
           input: document.querySelector("#full-name"),
           error: document.querySelector("#full-name-error"),
           validate(value) {
             return value.trim() ? "" : "Error: Enter your full name.";
           }
         },
         email: {
           input: document.querySelector("#email"),
           error: document.querySelector("#email-error"),
           validate(value) {
             const trimmed = value.trim();
             if (!trimmed) {
               return "Error: Enter your email address.";
             }

             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
               ? ""
               : "Error: Enter a valid email address, like name@example.com.";
           }
         },
         phone: {
           input: document.querySelector("#phone"),
           error: document.querySelector("#phone-error"),
           validate(value) {
             const trimmed = value.trim();
             const digitCount = trimmed.replace(/\D/g, "").length;

             if (!trimmed) {
               return "";
             }

             return /^\+?[0-9\s().-]+$/.test(trimmed) && digitCount >= 7 && digitCount <= 15
               ? ""
               : "Error: Enter a phone number with 7 to 15 digits. Use only numbers, spaces, dashes, parentheses, or a leading +.";
           }
         }
       };

       function setFieldError(field, message) {
         field.error.textContent = message;

         if (message) {
           field.input.setAttribute("aria-invalid", "true");
         } else {
           field.input.removeAttribute("aria-invalid");
         }
       }

       function validateField(field) {
         const message = field.validate(field.input.value);
         setFieldError(field, message);
         return !message;
       }

       Object.values(fields).forEach((field) => {
         field.input.addEventListener("blur", () => {
           validateField(field);
         });

         field.input.addEventListener("input", () => {
           if (field.input.getAttribute("aria-invalid") === "true") {
             validateField(field);
           }

           statusMessage.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const firstInvalidField = Object.values(fields).find((field) => !validateField(field));

         if (firstInvalidField) {
           statusMessage.textContent = "";
           firstInvalidField.input.focus();
           return;
         }

         form.reset();
         Object.values(fields).forEach((field) => setFieldError(field, ""));
         statusMessage.textContent = "Your request is ready to send. Thanks for contacting support.";
       });
     </script>
   </body>
